<?php $correction=$args['correction']??false;$received=sanitize_text_field(wp_unslash($_GET['received']??''));$error=sanitize_key($_GET['form-error']??''); ?>
<section id="contact-form" class="contact-panel"><h2><?php echo $correction?'Help us get it right.':'A thoughtful note starts here.'; ?></h2><div class="form-result" role="status" aria-live="polite"><?php if ($received && preg_match('/^[A-F0-9]{12}$/',$received)) { echo '<p class="notice success">Your message was saved in our private inbox. Reference: <strong>'.esc_html($received).'</strong>. No email confirmation is sent.</p>'; } elseif ($error) { echo '<p class="notice error">We could not accept that submission. Refresh the form, check the required fields and try again. If you recently sent several messages, wait an hour.</p>'; } ?></div>
<form id="message-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="gw_contact"><input type="hidden" name="kind" value="<?php echo $correction?'correction':'contact'; ?>"><input type="hidden" name="token" value="<?php echo esc_attr(gw_contact_token()); ?>"><div class="honeypot" aria-hidden="true"><label>Leave this field empty<input type="text" name="website" tabindex="-1" autocomplete="off" maxlength="200"></label></div>
<label>Your name<input name="name" autocomplete="name" required maxlength="80"></label><label>Reply email<input name="email" type="email" autocomplete="email" required maxlength="254"></label><p class="fine">Used to understand and follow up on your message. A reply is not guaranteed; no automated email is sent.</p><label>Subject<input name="subject" required minlength="3" maxlength="120"></label>
<?php if ($correction) { ?><label>Affected page URL<input name="source_page" type="url" required maxlength="1000" value="<?php $u=wp_unslash($_GET['page-url']??'');echo esc_attr(gw_valid_http_url($u)?$u:''); ?>"></label><label>Supporting source URL<input name="reference" type="url" required maxlength="1000"></label><?php } ?>
<label><?php echo $correction?'What should change, and why?':'Your message'; ?><textarea name="message" required minlength="20" maxlength="3000" rows="7" aria-describedby="message-hint"></textarea></label><p class="fine" id="message-hint">20–3,000 characters. Please omit passwords, payment details and sensitive health information.</p><label class="check-label"><input name="consent" type="checkbox" value="yes" required> I agree to the <a href="<?php echo esc_url(gw_link('privacy')); ?>">message handling and retention policy</a>.</label><button class="button" type="submit">Send <?php echo $correction?'correction':'message'; ?> <span aria-hidden="true">↗</span></button><p class="fine">Saved privately in WordPress. This form is not an email service.</p></form></section>
